def parse(tokens):
    pos = [0]
    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None
    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok
    def parse_factor():
        tok = advance()
        if tok == '(':
            node = parse_expr()
            advance()
            return node
        return tok
    def parse_term():
        node = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            node = (op, node, parse_factor())
        return node
    def parse_expr():
        node = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            node = (op, node, parse_term())
        return node
    return parse_expr()

